    if (!combos.length || !heroCards || !board || board.length < 5) return combos;

    const RS = global.GTORiverShoveNode;
    if (!RS) return combos;

    const deval = RS.pairedBoardFlushDevaluation(heroCards, board);
    if (!deval.vulnerable) return combos;

