    const tier = input.madeHandInfo && input.madeHandInfo.tier ? input.madeHandInfo.tier : '-';
    const nut = input.madeHandInfo && input.madeHandInfo.isNutStraight ? 'N' : '-';
    const shift = BTS() && input.priorBoard
