      check: 1 - betTotal,
      bet_33: betTotal * (split.s33 || 0),
      bet_66: betTotal * (split.s66 || 0),
      bet_100: betTotal * Math.max(0, (split.s100 || 0) - sOver * 0.5),
      overbet: betTotal * sOver
