    const penalties = { fold: 0.12, check: 0.08, call: 0.15, raise: 0.25, bet_33: 0.18, bet_66: 0.28, bet_100: 0.42 };
    return spotEV - (penalties[action] || 0.2) * pot * (penMul[tier] || 1);
